mapper.select:
SELECT pri.id AS id , pri.review_id AS reviewId , pri.original_file_name AS originalFileName , pri.stored_file_name AS storedFileName , pri.file_path AS filePath , pri.file_size AS fileSize , pri.sort_order AS sortOrder FROM place_review_image pri WHERE pri.review_id IN
#{reviewId}
ORDER BY pri.review_id ASC, pri.sort_order ASC
